require "test_helper"
require_relative "../test_helpers/session_test_helper"

# The token and revocation endpoints (generated by maquina:oauth).
class OauthTokensTest < ActionDispatch::IntegrationTest
  setup do
    @client = oauth_clients(:inspector)
  end

  test "exchanges a code for tokens, without caching" do
    exchange_code

    assert_response :success
    assert_equal "no-store", response.headers["Cache-Control"]
    body = response.parsed_body
    assert_equal "Bearer", body["token_type"]
    assert_equal 3600, body["expires_in"]
    assert_equal "read", body["scope"]
    assert body["refresh_token"].present?
    assert_equal users(:mcp_member), AccessToken.authenticate(body["access_token"]).user
  end

  test "a code works once" do
    exchange_code
    assert_response :success

    exchange_code

    assert_token_error "invalid_grant"
  end

  test "a code needs its PKCE verifier" do
    exchange_code(code_verifier: pkce_pair.first)

    assert_token_error "invalid_grant"
  end

  test "a code needs the resource it was issued for" do
    exchange_code(resource: "http://www.example.com/api")

    assert_token_error "invalid_target"
  end

  test "an expired code is refused" do
    travel OauthAuthorizationCode::TTL + 1.second

    exchange_code

    assert_token_error "invalid_grant"
  end

  test "the whole authorization code flow" do
    verifier, challenge = pkce_pair
    sign_in_as users(:mcp_admin)
    post oauth_authorization_path, params: authorize_params(challenge: challenge, scope: "read write").merge(decision: "allow")

    exchange_code(code: redirect_params["code"], code_verifier: verifier)

    assert_response :success
    assert_equal "read write", response.parsed_body["scope"]
    assert_equal users(:mcp_admin), AccessToken.authenticate(response.parsed_body["access_token"]).user
  end

  test "a refresh token rotates" do
    refresh

    assert_response :success
    body = response.parsed_body
    assert_not_equal MEMBER_READ_REFRESH_TOKEN, body["refresh_token"]
    assert_equal "read", body["scope"]
    assert AccessToken.authenticate(body["access_token"])
    assert_nil AccessToken.authenticate(MEMBER_READ_ACCESS_TOKEN), "the old access token stops with its row"
  end

  test "a refresh token works once" do
    refresh
    assert_response :success

    refresh

    assert_token_error "invalid_grant"
  end

  test "a refresh token sent by another client is refused" do
    OauthClient.create!(client_id: "https://other.example.com/client.json", client_name: "Other",
      redirect_uris: [INSPECTOR_REDIRECT_URI], metadata_fetched_at: Time.current)

    refresh(client_id: "https://other.example.com/client.json")

    assert_token_error "invalid_grant"
    assert AccessToken.authenticate(MEMBER_READ_ACCESS_TOKEN), "a refused refresh does not revoke the grant"
  end

  test "refuses an unknown grant type and missing parameters" do
    post oauth_token_path, params: {grant_type: "password", client_id: @client.client_id}
    assert_token_error "unsupported_grant_type"

    post oauth_token_path, params: {grant_type: "authorization_code", client_id: @client.client_id}
    assert_token_error "invalid_request"
  end

  test "revoking an unknown token answers 200" do
    post oauth_revocation_path, params: {token: "unknown", client_id: @client.client_id}

    assert_response :ok
    assert_empty response.body
    assert_equal "no-store", response.headers["Cache-Control"]
  end

  test "revokes an access or a refresh token for its own client only" do
    post oauth_revocation_path, params: {token: MEMBER_READ_ACCESS_TOKEN, client_id: "https://other.example.com/client.json"}
    assert_response :ok
    assert AccessToken.authenticate(MEMBER_READ_ACCESS_TOKEN)

    post oauth_revocation_path, params: {token: MEMBER_READ_ACCESS_TOKEN, client_id: @client.client_id}
    assert_response :ok
    assert_nil AccessToken.authenticate(MEMBER_READ_ACCESS_TOKEN)

    post oauth_revocation_path, params: {token: MEMBER_WRITE_REFRESH_TOKEN, client_id: @client.client_id}
    assert_nil AccessToken.authenticate(MEMBER_WRITE_ACCESS_TOKEN)
  end

  private

  def exchange_code(**overrides)
    params = {
      grant_type: "authorization_code",
      code: AUTHORIZATION_CODE,
      redirect_uri: INSPECTOR_REDIRECT_URI,
      client_id: @client.client_id,
      code_verifier: CODE_VERIFIER,
      resource: MCP_RESOURCE
    }
    post oauth_token_path, params: params.merge(overrides)
  end

  def refresh(**overrides)
    params = {grant_type: "refresh_token", refresh_token: MEMBER_READ_REFRESH_TOKEN, client_id: @client.client_id}
    post oauth_token_path, params: params.merge(overrides)
  end

  def assert_token_error(error)
    assert_response :bad_request
    assert_equal error, response.parsed_body["error"]
    assert_equal "no-store", response.headers["Cache-Control"]
  end
end
